            return this;
        }

        public SubscriptionHandle Subscribe() => new(conn, Applied, Error, querySqls.ToArray());
    }

    public abstract partial class Reducer
    {
        private Reducer() { }
    }

    public abstract partial class Procedure
    {
        private Procedure() { }
    }

    public sealed class DbConnection : DbConnectionBase<DbConnection, RemoteTables, Reducer>
    {
        public override RemoteTables Db { get; }
        public readonly RemoteReducers Reducers;
        public readonly RemoteProcedures Procedures;

        public DbConnection()
        {
            Db = new(this);
            Reducers = new(this);
            Procedures = new(this);
        }

        protected override IEventContext ToEventContext(Event<Reducer> Event) =>
        new EventContext(this, Event);

        protected override IReducerEventContext ToReducerEventContext(ReducerEvent<Reducer> reducerEvent) =>
        new ReducerEventContext(this, reducerEvent);

        protected override ISubscriptionEventContext MakeSubscriptionEventContext() =>
        new SubscriptionEventContext(this);

        protected override IErrorContext ToErrorContext(Exception exception) =>
        new ErrorContext(this, exception);

        protected override IProcedureEventContext ToProcedureEventContext(ProcedureEvent procedureEvent) =>
        new ProcedureEventContext(this, procedureEvent);

        protected override bool Dispatch(IReducerEventContext context, Reducer reducer)
        {
            var eventContext = (ReducerEventContext)context;
            return reducer switch
            {
                Reducer.BenchGenerate args => Reducers.InvokeBenchGenerate(eventContext, args),
                Reducer.ClearBiomes args => Reducers.InvokeClearBiomes(eventContext, args),
                Reducer.ClearEnemies args => Reducers.InvokeClearEnemies(eventContext, args),
                Reducer.ClearEnemyLoot args => Reducers.InvokeClearEnemyLoot(eventContext, args),
                Reducer.ClearLoot args => Reducers.InvokeClearLoot(eventContext, args),
                Reducer.ClearPhases args => Reducers.InvokeClearPhases(eventContext, args),
                Reducer.ClearSpawners args => Reducers.InvokeClearSpawners(eventContext, args),
                Reducer.ClearTerrain args => Reducers.InvokeClearTerrain(eventContext, args),
                Reducer.CloseBag args => Reducers.InvokeCloseBag(eventContext, args),
                Reducer.CreateCharacter args => Reducers.InvokeCreateCharacter(eventContext, args),
                Reducer.DepositToVault args => Reducers.InvokeDepositToVault(eventContext, args),
                Reducer.EquipWeapon args => Reducers.InvokeEquipWeapon(eventContext, args),
                Reducer.GenerateRealm args => Reducers.InvokeGenerateRealm(eventContext, args),
                Reducer.GiveTestItem args => Reducers.InvokeGiveTestItem(eventContext, args),
                Reducer.KillMe args => Reducers.InvokeKillMe(eventContext, args),
                Reducer.LeaveCharacter args => Reducers.InvokeLeaveCharacter(eventContext, args),
                Reducer.Move args => Reducers.InvokeMove(eventContext, args),
                Reducer.MoveItem args => Reducers.InvokeMoveItem(eventContext, args),
                Reducer.MoveVaultItem args => Reducers.InvokeMoveVaultItem(eventContext, args),
                Reducer.OpenBag args => Reducers.InvokeOpenBag(eventContext, args),
                Reducer.Reload args => Reducers.InvokeReload(eventContext, args),
                Reducer.RerollRealm args => Reducers.InvokeRerollRealm(eventContext, args),
                Reducer.ResetTickMetrics args => Reducers.InvokeResetTickMetrics(eventContext, args),
                Reducer.SelectCharacter args => Reducers.InvokeSelectCharacter(eventContext, args),
                Reducer.SetName args => Reducers.InvokeSetName(eventContext, args),
                Reducer.SetSpawn args => Reducers.InvokeSetSpawn(eventContext, args),
                Reducer.SetTickInterval args => Reducers.InvokeSetTickInterval(eventContext, args),
                Reducer.Shoot args => Reducers.InvokeShoot(eventContext, args),
                Reducer.SpawnEnemies args => Reducers.InvokeSpawnEnemies(eventContext, args),
                Reducer.SpawnEnemy args => Reducers.InvokeSpawnEnemy(eventContext, args),
                Reducer.TakeAllFromBag args => Reducers.InvokeTakeAllFromBag(eventContext, args),
                Reducer.TakeFromBag args => Reducers.InvokeTakeFromBag(eventContext, args),
                Reducer.UpsertBiome args => Reducers.InvokeUpsertBiome(eventContext, args),
                Reducer.UpsertEnemyDef args => Reducers.InvokeUpsertEnemyDef(eventContext, args),
                Reducer.UpsertEnemyLoot args => Reducers.InvokeUpsertEnemyLoot(eventContext, args),
                Reducer.UpsertItemDef args => Reducers.InvokeUpsertItemDef(eventContext, args),
                Reducer.UpsertLoot args => Reducers.InvokeUpsertLoot(eventContext, args),
                Reducer.UpsertLootPool args => Reducers.InvokeUpsertLootPool(eventContext, args),
                Reducer.UpsertPhase args => Reducers.InvokeUpsertPhase(eventContext, args),
                Reducer.UpsertPlayerConfig args => Reducers.InvokeUpsertPlayerConfig(eventContext, args),
                Reducer.UpsertRealmConfig args => Reducers.InvokeUpsertRealmConfig(eventContext, args),
                Reducer.UpsertSpawner args => Reducers.InvokeUpsertSpawner(eventContext, args),
                Reducer.UpsertTerrainChunk args => Reducers.InvokeUpsertTerrainChunk(eventContext, args),
                Reducer.UpsertWeapon args => Reducers.InvokeUpsertWeapon(eventContext, args),
                Reducer.UseAuthoredTerrain args => Reducers.InvokeUseAuthoredTerrain(eventContext, args),
                Reducer.WithdrawFromVault args => Reducers.InvokeWithdrawFromVault(eventContext, args),
                _ => throw new ArgumentOutOfRangeException("Reducer", $"Unknown reducer {reducer}")
            };
        }

        public SubscriptionBuilder SubscriptionBuilder() => new(this);
        public event Action<ReducerEventContext, Exception> OnUnhandledReducerError
        {
            add => Reducers.InternalOnUnhandledReducerError += value;
            remove => Reducers.InternalOnUnhandledReducerError -= value;
        }
    }
}
